<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {qualityWorkspace,qualityCommand} from '@/services/quality'
const props=defineProps<{kind:'auditor'|'area'}>(),emit=defineEmits(['close','changed'])
const rows=ref<any[]>([]),edit=ref<any>(null),error=ref(''),busy=ref(false)
async function load(){const d=await qualityWorkspace();rows.value=props.kind==='auditor'?d.auditors:d.areas;emit('changed',d)}
onMounted(()=>load().catch(e=>error.value=e.message))
async function save(){error.value='';if(!edit.value.name?.trim()){error.value='Indique o nome.';return}busy.value=true;try{await qualityCommand(props.kind==='auditor'?'auditor_save':'area_save',edit.value.id||null,edit.value);edit.value=null;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function remove(r:any){if(!confirm('Eliminar este valor se nunca foi utilizado? Esta operação é definitiva.'))return;try{await qualityCommand('config_delete',r.id,{kind:props.kind,confirm_delete:true});await load()}catch(e){error.value=(e as Error).message}}
</script>
<template><div class="modal d-block" role="dialog" aria-modal="true" :aria-label="kind==='auditor'?'Gerir Auditores':'Gerir Áreas/Processos'" style="background:#0007;z-index:1070"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h2 class="fs-5">{{kind==='auditor'?'Gerir Auditores':'Gerir Áreas/Processos'}}</h2><button class="btn-close" aria-label="Voltar ao formulário" @click="emit('close')"/></div><div class="modal-body"><p>Este catálogo pertence à empresa selecionada. Ao regressar, os dados já preenchidos no formulário são mantidos.</p><div v-if="error" class="alert alert-danger" role="alert">{{error}}</div><button class="btn btn-primary mb-3" @click="edit={name:'',kind:'EXTERNAL',active:true}">Adicionar</button><form v-if="edit" novalidate @submit.prevent="save" class="border rounded p-3 mb-3"><label class="form-label">Nome<input v-model="edit.name" class="form-control"/></label><template v-if="kind==='auditor'"><label class="form-label ms-2">Tipo<select v-model="edit.kind" class="form-select"><option value="INTERNAL">Interno</option><option value="EXTERNAL">Externo</option></select></label><label class="form-label d-block">Entidade<input v-model="edit.entity" class="form-control"/></label><label class="form-label d-block">Contacto opcional<input v-model="edit.contact" class="form-control"/></label><p class="small">Um auditor externo não necessita de conta na aplicação.</p></template><label class="d-block"><input v-model="edit.active" type="checkbox"/> Ativo</label><div class="d-flex gap-2 mt-2"><button class="btn btn-primary" :disabled="busy">Guardar</button><button type="button" class="btn btn-outline-secondary" @click="edit=null">Cancelar</button></div></form><div v-for="r in rows" :key="r.id" class="border-bottom py-2 d-flex gap-2 align-items-center flex-wrap"><span class="me-auto">{{r.name}} · {{r.active?'Ativo':'Inativo'}} {{r.kind==='EXTERNAL'?'· Externo':''}}</span><button class="btn btn-sm btn-outline-primary" @click="edit={...r}">Editar</button><button class="btn btn-sm btn-outline-secondary" @click="edit={...r,active:!r.active};save()">{{r.active?'Desativar':'Ativar'}}</button><button class="btn btn-sm btn-outline-danger" @click="remove(r)">Eliminar</button></div></div><div class="modal-footer"><button class="btn btn-primary" @click="emit('close')">Voltar ao formulário</button></div></div></div></div></template>
